/**
 * Tests for AddressVerificationService.
 *
 * They pin the documented behaviour of verify(acct), including the HTTP request
 * contract (method, endpoint, Content-Type header and JSON body), the SKIPPED
 * short-circuit, every documented response status and the non-200 error path.
 */
@IsTest
private class AddressVerificationServiceTest {

    private static final String STREET = '1 Main St';
    private static final String CITY = 'Springfield';
    private static final String POSTAL_CODE = '12345';
    private static final String COUNTRY = 'USA';

    // A "corrected" address whose four values differ from the account's own values,
    // so that a swapped or missing assignment cannot go unnoticed.
    private static final String RETURNED_ADDRESS =
        '"address":{"street":"2 Correct Ave","city":"Rightville","postalCode":"54321","country":"Canada"}';

    private static final String CORRECTED_BODY = '{"status":"CORRECTED",' + RETURNED_ADDRESS + '}';
    private static final String VERIFIED_BODY = '{"status":"VERIFIED",' + RETURNED_ADDRESS + '}';
    private static final String INVALID_BODY = '{"status":"INVALID",' + RETURNED_ADDRESS + '}';
    private static final String PENDING_BODY = '{"status":"PENDING",' + RETURNED_ADDRESS + '}';

    // ------------------------------------------------------------------- Mocks

    /** Returns a canned response and remembers the request it was handed. */
    private class JsonResponseMock implements HttpCalloutMock {
        private final Integer statusCode;
        private final String responseBody;
        public HttpRequest lastRequest;

        public JsonResponseMock(Integer statusCode, String responseBody) {
            this.statusCode = statusCode;
            this.responseBody = responseBody;
        }

        public HttpResponse respond(HttpRequest request) {
            lastRequest = request;
            HttpResponse response = new HttpResponse();
            response.setStatusCode(statusCode);
            response.setHeader('Content-Type', 'application/json');
            response.setBody(responseBody);
            return response;
        }
    }

    /** Returns the given status codes, one per call, in order. */
    private class StatusSequenceMock implements HttpCalloutMock {
        private final List<Integer> statusCodes;
        private Integer nextIndex = 0;

        public StatusSequenceMock(List<Integer> statusCodes) {
            this.statusCodes = statusCodes;
        }

        public HttpResponse respond(HttpRequest request) {
            Integer statusCode = statusCodes[nextIndex];
            nextIndex++;
            HttpResponse response = new HttpResponse();
            response.setStatusCode(statusCode);
            response.setHeader('Content-Type', 'application/json');
            response.setBody(VERIFIED_BODY);
            return response;
        }
    }

    /** Fails the test if the service makes a callout when it must not. */
    private class UnexpectedCalloutMock implements HttpCalloutMock {
        public HttpResponse respond(HttpRequest request) {
            System.assert(false, 'No callout expected, but one was sent to ' + request.getEndpoint());
            return null;
        }
    }

    // ----------------------------------------------------------------- Helpers

    private static Account newAccount() {
        return new Account(
            Name = 'Acme Corp',
            BillingStreet = STREET,
            BillingCity = CITY,
            BillingPostalCode = POSTAL_CODE,
            BillingCountry = COUNTRY
        );
    }

    /** Asserts that verify() left the account exactly as it was. */
    private static void assertUnchanged(Account acct) {
        System.assertEquals(STREET, acct.BillingStreet, 'BillingStreet should not have been modified');
        System.assertEquals(CITY, acct.BillingCity, 'BillingCity should not have been modified');
        System.assertEquals(POSTAL_CODE, acct.BillingPostalCode, 'BillingPostalCode should not have been modified');
        System.assertEquals(COUNTRY, acct.BillingCountry, 'BillingCountry should not have been modified');
    }

    private static Map<String, Object> requestBodyOf(HttpRequest request) {
        System.assertNotEquals(null, request, 'A callout should have been made');
        return (Map<String, Object>) JSON.deserializeUntyped(request.getBody());
    }

    // ------------------------------------------------------------------- Tests

    @IsTest
    static void blankBillingStreetIsSkippedWithoutCallout() {
        Test.setMock(HttpCalloutMock.class, new UnexpectedCalloutMock());

        Account whitespaceStreet = new Account(
            Name = 'Whitespace Co',
            BillingStreet = '   ',
            BillingCity = CITY,
            BillingPostalCode = POSTAL_CODE,
            BillingCountry = COUNTRY
        );
        Account nullStreet = new Account(
            Name = 'Null Street Co',
            BillingStreet = null,
            BillingCity = CITY,
            BillingPostalCode = POSTAL_CODE,
            BillingCountry = COUNTRY
        );

        Test.startTest();
        AddressVerificationService.Result whitespaceResult = AddressVerificationService.verify(whitespaceStreet);
        AddressVerificationService.Result nullResult = AddressVerificationService.verify(nullStreet);
        Test.stopTest();

        System.assertEquals('SKIPPED', whitespaceResult.status, 'A whitespace-only BillingStreet must be skipped');
        System.assertEquals(false, whitespaceResult.changed, 'A skipped verification must not report a change');
        System.assertEquals('   ', whitespaceStreet.BillingStreet, 'A skipped account must be left untouched');
        System.assertEquals(CITY, whitespaceStreet.BillingCity, 'A skipped account must be left untouched');
        System.assertEquals(POSTAL_CODE, whitespaceStreet.BillingPostalCode, 'A skipped account must be left untouched');
        System.assertEquals(COUNTRY, whitespaceStreet.BillingCountry, 'A skipped account must be left untouched');

        System.assertEquals('SKIPPED', nullResult.status, 'A null BillingStreet must be skipped');
        System.assertEquals(false, nullResult.changed, 'A skipped verification must not report a change');
        System.assertEquals(null, nullStreet.BillingStreet, 'A skipped account must be left untouched');
        System.assertEquals(CITY, nullStreet.BillingCity, 'A skipped account must be left untouched');
        System.assertEquals(POSTAL_CODE, nullStreet.BillingPostalCode, 'A skipped account must be left untouched');
        System.assertEquals(COUNTRY, nullStreet.BillingCountry, 'A skipped account must be left untouched');
    }

    @IsTest
    static void sendsTheDocumentedRequest() {
        Account acct = newAccount();
        JsonResponseMock mock = new JsonResponseMock(200, VERIFIED_BODY);
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        AddressVerificationService.verify(acct);
        Test.stopTest();

        HttpRequest request = mock.lastRequest;
        System.assertNotEquals(null, request, 'A callout must be made for a non-blank BillingStreet');
        System.assertEquals('callout:FB_Address_API/v2/verify', request.getEndpoint(), 'Unexpected endpoint');
        System.assertEquals('POST', request.getMethod(), 'Unexpected HTTP method');
        System.assertEquals('application/json', request.getHeader('Content-Type'), 'Unexpected Content-Type header');

        Map<String, Object> body = requestBodyOf(request);
        System.assertEquals(4, body.size(), 'The body must contain exactly the four documented address keys');
        System.assertEquals(STREET, body.get('street'), 'Wrong street in the request body');
        System.assertEquals(CITY, body.get('city'), 'Wrong city in the request body');
        System.assertEquals(POSTAL_CODE, body.get('postalCode'), 'Wrong postalCode in the request body');
        System.assertEquals(COUNTRY, body.get('country'), 'Wrong country in the request body');
    }

    @IsTest
    static void requestBodyAlwaysCarriesAllFourAddressKeys() {
        Account acct = newAccount();
        acct.BillingCity = '';
        acct.BillingCountry = '';
        JsonResponseMock mock = new JsonResponseMock(200, INVALID_BODY);
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        AddressVerificationService.verify(acct);
        Test.stopTest();

        Map<String, Object> body = requestBodyOf(mock.lastRequest);
        System.assertEquals(4, body.size(), 'The body must always contain the four documented address keys');
        System.assertEquals(STREET, body.get('street'), 'Wrong street in the request body');
        System.assertEquals('', body.get('city'), 'A blank city must still be sent as its own value');
        System.assertEquals(POSTAL_CODE, body.get('postalCode'), 'Wrong postalCode in the request body');
        System.assertEquals('', body.get('country'), 'A blank country must still be sent as its own value');
    }

    @IsTest
    static void verifiedResponseIsReportedWithoutChangingTheAccount() {
        Account acct = newAccount();
        Test.setMock(HttpCalloutMock.class, new JsonResponseMock(200, VERIFIED_BODY));

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('VERIFIED', result.status, 'The response status must be reported as-is');
        System.assertEquals(false, result.changed, 'VERIFIED must not report a change');
        assertUnchanged(acct);
    }

    @IsTest
    static void invalidResponseIsReportedWithoutChangingTheAccount() {
        Account acct = newAccount();
        Test.setMock(HttpCalloutMock.class, new JsonResponseMock(200, INVALID_BODY));

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('INVALID', result.status, 'The response status must be reported as-is');
        System.assertEquals(false, result.changed, 'INVALID must not report a change');
        assertUnchanged(acct);
    }

    @IsTest
    static void anyOtherStatusIsReportedWithoutChangingTheAccount() {
        Account acct = newAccount();
        Test.setMock(HttpCalloutMock.class, new JsonResponseMock(200, PENDING_BODY));

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('PENDING', result.status, 'The response status must be reported as-is');
        System.assertEquals(false, result.changed, 'Only CORRECTED reports a change');
        assertUnchanged(acct);
    }

    @IsTest
    static void correctedResponseOverwritesTheBillingFields() {
        Account acct = newAccount();
        Test.setMock(HttpCalloutMock.class, new JsonResponseMock(200, CORRECTED_BODY));

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('CORRECTED', result.status, 'The response status must be reported as-is');
        System.assertEquals(true, result.changed, 'A corrected address must report changed = true');
        System.assertEquals('2 Correct Ave', acct.BillingStreet, 'BillingStreet must take the returned street');
        System.assertEquals('Rightville', acct.BillingCity, 'BillingCity must take the returned city');
        System.assertEquals('54321', acct.BillingPostalCode, 'BillingPostalCode must take the returned postalCode');
        System.assertEquals('Canada', acct.BillingCountry, 'BillingCountry must take the returned country');
    }

    @IsTest
    static void anyStatusOtherThan200ThrowsWithTheStatusCode() {
        List<Integer> statusCodes = new List<Integer>{ 201, 204, 400, 500, 503 };
        Test.setMock(HttpCalloutMock.class, new StatusSequenceMock(statusCodes));

        Test.startTest();
        for (Integer statusCode : statusCodes) {
            assertThrowsWithStatusCode(statusCode);
        }
        Test.stopTest();
    }

    private static void assertThrowsWithStatusCode(Integer statusCode) {
        Account acct = newAccount();

        AddressVerificationService.AddressVerificationException caught;
        try {
            AddressVerificationService.verify(acct);
        } catch (AddressVerificationService.AddressVerificationException e) {
            caught = e;
        }

        System.assertNotEquals(null, caught, 'HTTP ' + statusCode + ' must throw AddressVerificationException');
        System.assert(
            caught.getMessage().contains(String.valueOf(statusCode)),
            'The exception message must contain the status code ' + statusCode + ' but was: ' + caught.getMessage()
        );
        assertUnchanged(acct);
    }
}
