public without sharing class OpportunityPipelineHandler {
    public static void handle() {
        Set<Id> accountIds = new Set<Id>();

        if (Trigger.isInsert || Trigger.isUndelete) {
            for (Opportunity opp : (List<Opportunity>) Trigger.new) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        } else if (Trigger.isDelete) {
            for (Opportunity opp : (List<Opportunity>) Trigger.old) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        } else if (Trigger.isUpdate) {
            for (Opportunity opp : (List<Opportunity>) Trigger.new) {
                Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);
                if (opp.AccountId != oldOpp.AccountId
                    || opp.Amount != oldOpp.Amount
                    || opp.IsClosed != oldOpp.IsClosed) {
                    if (opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                    if (oldOpp.AccountId != null) {
                        accountIds.add(oldOpp.AccountId);
                    }
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        recalculateAccounts(accountIds);
    }

    private static void recalculateAccounts(Set<Id> accountIds) {
        Map<Id, Decimal> sumByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) total, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('AccountId');
            Decimal total = (Decimal) ar.get('total');
            Integer cnt = (Integer) ar.get('cnt');
            sumByAccount.put(accId, total == null ? 0 : total);
            countByAccount.put(accId, cnt == null ? 0 : cnt);
        }

        Map<Id, Account> currentAccounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Account current = currentAccounts.get(accId);
            if (current == null) {
                continue;
            }

            Decimal total = sumByAccount.containsKey(accId) ? sumByAccount.get(accId) : 0;
            Integer cnt = countByAccount.containsKey(accId) ? countByAccount.get(accId) : 0;

            Decimal currentTotal = current.FB_Open_Pipeline__c == null ? 0 : current.FB_Open_Pipeline__c;
            Decimal currentCount = current.FB_Open_Opportunities__c == null ? 0 : current.FB_Open_Opportunities__c;

            if (currentTotal != total || currentCount != cnt) {
                accountsToUpdate.add(new Account(
                    Id = accId,
                    FB_Open_Pipeline__c = total,
                    FB_Open_Opportunities__c = cnt
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
