/**
 * Unit tests for OpportunityForecastService.weightedAmountByStage.
 *
 * These are pure unit tests: no DML and no SOQL is executed.
 *   - IOpportunitiesSelector is replaced by an ApexMocks mock which is
 *     registered on the Application.Selector factory, so that
 *     OpportunitiesSelector.newInstance() hands the mock back to the service.
 *   - Opportunity records are built in memory with fake ids coming from
 *     fflib_IDGenerator (no database required).
 */
@IsTest
private class OpportunityForecastServiceTest {

    private static final String STAGE_PROSPECTING  = 'Prospecting';
    private static final String STAGE_QUALIFICATION = 'Qualification';
    private static final String STAGE_PROPOSAL     = 'Proposal/Price Quote';

    private static fflib_ApexMocks mocks;
    private static IOpportunitiesSelector mockSelector;

    // ---------------------------------------------------------------------
    // Test helpers
    // ---------------------------------------------------------------------

    /**
     * Creates a fresh mock selector and registers it on the selector factory
     * so that OpportunitiesSelector.newInstance() returns the mock instead of
     * instantiating the real selector (and therefore never touches the DB).
     */
    private static void registerMockSelector() {
        mocks = new fflib_ApexMocks();
        mockSelector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, mockSelector);
    }

    /**
     * Builds an in-memory Opportunity with a fake id.
     */
    private static Opportunity openOpportunity(String stageName, Decimal amount, Decimal probability, Id accountId) {
        return new Opportunity(
            Id          = fflib_IDGenerator.generate(Opportunity.SObjectType),
            AccountId   = accountId,
            Name        = 'Unit Test Opportunity',
            StageName   = stageName,
            Amount      = amount,
            Probability = probability,
            CloseDate   = Date.today().addDays(30)
        );
    }

    /**
     * Stubs the mocked selector. The very same Set instance that is handed to
     * the service is used here, so the stub always matches the service call.
     */
    private static void stubOpenOpportunities(Set<Id> accountIds, List<Opportunity> opportunities) {
        mocks.startStubbing();
        mocks.when(mockSelector.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();
    }

    // ---------------------------------------------------------------------
    // Tests
    // ---------------------------------------------------------------------

    /**
     * Weighted amounts (Amount * Probability / 100) are summed per StageName.
     */
    @IsTest
    static void sumsWeightedAmountPerStageName() {
        registerMockSelector();

        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId };

        stubOpenOpportunities(accountIds, new List<Opportunity>{
            openOpportunity(STAGE_PROSPECTING,   1000, 50, accountId), // 1000 * 50 / 100 = 500.00
            openOpportunity(STAGE_PROSPECTING,    200, 25, accountId), //  200 * 25 / 100 =  50.00
            openOpportunity(STAGE_QUALIFICATION,  400, 10, accountId)  //  400 * 10 / 100 =  40.00
        });

        Test.startTest();
        Map<String, Decimal> totals = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        System.assertEquals(2, totals.size(),
            'One entry per stage name that has open opportunities is expected');
        System.assertEquals(Decimal.valueOf('550.00'), totals.get(STAGE_PROSPECTING),
            'Prospecting should be 500.00 + 50.00');
        System.assertEquals(Decimal.valueOf('40.00'), totals.get(STAGE_QUALIFICATION),
            'Qualification should be 40.00');
        System.assertEquals(false, totals.containsKey(STAGE_PROPOSAL),
            'Stages with no open opportunities must not appear in the result');

        ((IOpportunitiesSelector) mocks.verify(mockSelector)).selectOpenByAccountIds(accountIds);
    }

    /**
     * Each opportunity is rounded to 2 decimals *before* being added to the
     * running total (and not just once at the end).
     */
    @IsTest
    static void roundsEachOpportunityToTwoDecimalsBeforeSumming() {
        registerMockSelector();

        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId };

        // 10 * 33.33 / 100 = 3.333 -> 3.33 per opportunity, 3.33 * 3 = 9.99.
        // Rounding only the grand total would give 10.00 instead.
        stubOpenOpportunities(accountIds, new List<Opportunity>{
            openOpportunity(STAGE_PROSPECTING, 10, 33.33, accountId),
            openOpportunity(STAGE_PROSPECTING, 10, 33.33, accountId),
            openOpportunity(STAGE_PROSPECTING, 10, 33.33, accountId)
        });

        Test.startTest();
        Map<String, Decimal> totals = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        System.assertEquals(1, totals.size(), 'All three opportunities belong to the same stage');
        System.assertEquals(Decimal.valueOf('9.99'), totals.get(STAGE_PROSPECTING),
            'Each weighted amount must be rounded to 2 decimals before it is summed');
    }

    /**
     * Opportunities that have no Amount or no Probability are ignored.
     */
    @IsTest
    static void ignoresOpportunitiesWithoutAmountOrProbability() {
        registerMockSelector();

