/**
 * Domain class for the Opportunity SObject.
 *
 * Validation rules:
 *  1. Amount cannot be negative (on insert and on update).
 *  2. Amount cannot change on an opportunity whose stage was already
 *     'Closed Won' before the update. Closing an opportunity as won and
 *     changing its amount in the same update is allowed, because the old
 *     record only holds 'Closed Won' when it was already won.
 *
 * Both errors are raised through the fflib error(message, record, field)
 * helper so that they are registered on the offending record's Amount field
 * (blocking only that record) and collected in fflib_SObjectDomain.Errors
 * for unit tests. No SOQL is required - old values come from Trigger.oldMap.
 */
public class Opportunities extends fflib_SObjectDomain
{
    /**
     * Standard fflib constructor class used by
     * fflib_SObjectDomain.triggerHandler to instantiate the domain.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    public Opportunities(List<Opportunity> sObjectList)
    {
        super(sObjectList);
    }

    public override void onValidate()
    {
        // fflib invokes onValidate() from every trigger event, including the
        // after events and the delete/undelete events. These rules only apply
        // to records that are about to be inserted or updated.
        if (Trigger.isAfter || Trigger.isDelete || Trigger.isUndelete)
        {
            return;
        }

        // Old records are only available on update; on insert this map is empty.
        Map<Id, SObject> oldRecordsById =
            Trigger.isUpdate ? Trigger.oldMap : new Map<Id, SObject>();

        for (Opportunity opp : (List<Opportunity>) getRecords())
        {
            // Rule 1 - Amount cannot be negative (insert and update).
            if (opp.Amount != null && opp.Amount < 0)
            {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }

            // Rule 2 - Amount cannot change on an opportunity that was
            // already Closed Won before this update.
            SObject oldRecord = oldRecordsById.get(opp.Id);

            if (oldRecord != null)
            {
                Opportunity oldOpp = (Opportunity) oldRecord;

                if (oldOpp.StageName == 'Closed Won' && opp.Amount != oldOpp.Amount)
                {
                    error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                }
            }
        }
    }
}
