import { LightningElement, wire } from 'lwc';
import {
    APPLICATION_SCOPE,
    MessageContext,
    publish,
    subscribe,
    unsubscribe
} from 'lightning/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    /** Lightning message service context for this component. */
    @wire(MessageContext)
    messageContext;

    /** Handle of the single active subscription (null when not subscribed). */
    subscription = null;

    /** True while this component holds a subscription. Tracked separately so we
     *  can always unsubscribe, even if the subscribe call returns nothing. */
    isSubscribed = false;

    /** Id of the selected account; null/undefined means "nothing selected". */
    recordId;

    connectedCallback() {
        // Subscribe on every insertion, including re-insertion (e.g. tab reopened).
        this.subscribeToMessageChannel();
    }

    disconnectedCallback() {
        // Never leave a subscription behind when the component goes away.
        this.unsubscribeFromMessageChannel();
    }

    subscribeToMessageChannel() {
        // Guard so the component never holds more than one subscription.
        if (this.isSubscribed) {
            return;
        }

        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
        this.isSubscribed = true;
    }

    unsubscribeFromMessageChannel() {
        if (this.isSubscribed) {
            unsubscribe(this.subscription);
            this.subscription = null;
            this.isSubscribed = false;
        }
    }

    handleMessage(message) {
        // A message with no recordId (or an explicit null) clears the panel.
        this.recordId = (message && message.recordId) || null;
    }

    handleClear() {
        // Broadcast the clear so every listener, including this panel, resets.
        publish(this.messageContext, ACCOUNT_SELECTED, { recordId: null });
    }
}
