public with sharing class HouseholdService {

    /**
     * Thrown when NPSP fails to produce the Household Account we depend on.
     */
    public class HouseholdServiceException extends Exception {}

    /**
     * Creates ONE new NPSP Household Account and puts every supplied Contact in it.
     * The first Contact in the list becomes the household's primary contact.
     *
     * @param members New Contacts (no Id, no AccountId) to register as one household.
     * @return Id of the Household Account that NPSP created.
     * @throws IllegalArgumentException if members is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must contain at least one Contact.');
        }

        // 1) Insert the first contact on its own. Because no AccountId is supplied,
        //    NPSP's household logic (ACCT_IndividualAccounts_TDTM) creates a Household
        //    Account for it, names it, generates greetings and sets
        //    Account.npe01__One2OneContact__c to this contact. We never set the name.
        Contact primaryContact = members[0];
        insert primaryContact;

        // 2) Read back the household the NPSP trigger created. A re-query is used because
        //    AccountId is written by an after-insert trigger via a separate DML statement
        //    and is therefore not guaranteed to be reflected on the in-memory record.
        Id householdId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primaryContact.Id
        ].AccountId;

        if (householdId == null) {
            throw new HouseholdServiceException(
                'NPSP did not create a Household Account for the primary contact.'
            );
        }

        // 3) Attach every remaining family member to that same household. Setting
        //    AccountId up front means NPSP will not create a second household for them.
        if (members.size() > 1) {
            List<Contact> additionalMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact member = members[i];
                member.AccountId = householdId;
                additionalMembers.add(member);
            }
            insert additionalMembers;
        }

        return householdId;
    }
}
