public with sharing class SoftCreditService {
    public class SoftCreditException extends Exception {}
    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    private static final String KEY_SEP = '|';

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---- Normalise input: one entry per opportunity/contact pair ----
        Map<String, SoftCreditRequest> requestsByKey = new Map<String, SoftCreditRequest>();
        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Each request must specify an Opportunity and a Contact.');
            }
            String key = keyFor(req.opportunityId, req.contactId);
            if (!requestsByKey.containsKey(key)) {
                requestsByKey.put(key, req);
            }
            opportunityIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ---- Query 1: opportunities (needed for primary contact + amount checks) ----
        Map<Id, Opportunity> opportunities = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]);

        // ---- Query 2: existing Opportunity Contact Roles for the pairs in play ----
        Map<String, List<OpportunityContactRole>> ocrsByKey =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds AND ContactId IN :contactIds
        ]) {
            String key = keyFor(ocr.OpportunityId, ocr.ContactId);
            if (!ocrsByKey.containsKey(key)) {
                ocrsByKey.put(key, new List<OpportunityContactRole>());
            }
            ocrsByKey.get(key).add(ocr);
        }

        // ---- Query 3: existing partial soft credits for the pairs in play ----
        Map<String, List<npsp__Partial_Soft_Credit__c>> pscsByKey =
            new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            String key = keyFor(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!pscsByKey.containsKey(key)) {
                pscsByKey.put(key, new List<npsp__Partial_Soft_Credit__c>());
            }
            pscsByKey.get(key).add(psc);
        }

        // ---- Validate the whole call before any DML happens ----
        for (SoftCreditRequest req : requestsByKey.values()) {
            Opportunity opp = opportunities.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be a positive number.');
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount cannot exceed the opportunity amount.'
                );
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'The primary contact of an opportunity cannot receive a soft credit.'
                );
            }
        }

        // ---- Work out the contact role changes (one role per contact, named req.role) ----
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> chosenOcrByKey =
            new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requestsByKey.values()) {
            String key = keyFor(req.opportunityId, req.contactId);
            List<OpportunityContactRole> existing = ocrsByKey.get(key);
            OpportunityContactRole ocr;

            if (existing != null && !existing.isEmpty()) {
                // Reuse the first role (e.g. NPSP's "Household Member"), retarget it,
                // and remove any extra roles so exactly one remains.
                ocr = existing[0];
                if (ocr.Role != req.role) {
                    ocr.Role = req.role;
                    ocrsToUpsert.add(ocr);
                }
                for (Integer i = 1; i < existing.size(); i++) {
                    ocrsToDelete.add(existing[i]);
                }
            } else {
                ocr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToUpsert.add(ocr);
            }
            chosenOcrByKey.put(key, ocr);
        }

        // ---- DML 1 & 2: align the contact roles ----
        if (!ocrsToUpsert.isEmpty()) {
            upsert ocrsToUpsert;
        }
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }

        // ---- Work out the partial soft credit changes ----
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToDelete =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requestsByKey.values()) {
            String key = keyFor(req.opportunityId, req.contactId);
            OpportunityContactRole ocr = chosenOcrByKey.get(key);
            if (ocr == null || ocr.Id == null) {
                throw new SoftCreditException(
                    'Unable to resolve the contact role for the soft credit.'
                );
            }

            List<npsp__Partial_Soft_Credit__c> existing = pscsByKey.get(key);
            npsp__Partial_Soft_Credit__c psc;

            if (existing != null && !existing.isEmpty()) {
                // Update in place instead of creating a second soft credit.
                psc = existing[0];
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = ocr.Id;
                pscsToUpsert.add(psc);
                for (Integer i = 1; i < existing.size(); i++) {
                    pscsToDelete.add(existing[i]);
                }
            } else {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = ocr.Id
                );
                pscsToUpsert.add(psc);
            }
        }

        // ---- DML 3 & 4: align the partial soft credits ----
        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }
        if (!pscsToDelete.isEmpty()) {
            delete pscsToDelete;
        }
    }

    private static String keyFor(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + KEY_SEP + String.valueOf(contactId);
    }
