public with sharing class RecordAccessService {
    private static final Integer BATCH_SIZE = 100;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        List<Id> ids = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                ids.add(recordId);
            }
        }

        if (ids.isEmpty()) {
            return new Set<Id>();
        }

        Set<Id> editable = new Set<Id>();
        Id userId = UserInfo.getUserId();

        for (Integer i = 0; i < ids.size(); i += BATCH_SIZE) {
            Integer batchEnd = Math.min(i + BATCH_SIZE, ids.size());
            List<Id> batch = new List<Id>();
            for (Integer j = i; j < batchEnd; j++) {
                batch.add(ids[j]);
            }

            for (UserRecordAccess ura : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :userId
                  AND RecordId IN :batch
                  AND HasEditAccess = true
            ]) {
                editable.add(ura.RecordId);
            }
        }

        return editable;
    }
}
