/**
 * TA_Opportunity_LogAmountChange
 *
 * After update action on Opportunity: creates a completed Task whenever an
 * Opportunity's Amount is changed by an update.
 *
 * TA_Opportunity_RoundAmount (Order__c 20) re-updates the same Opportunities in
 * the same transaction, which re-runs every Opportunity after update action.
 * That second pass is a consequence of the change the user made, not a new
 * change, so it must not create another Task. Each Opportunity Id is therefore
 * evaluated only the first time it is seen in the after update context of the
 * transaction (the same guarantee the framework's
 * TriggerBase.idToNumberOfTimesSeenAfterUpdate counter provides); the Ids are
 * held in a static Set, which Apex scopes to the transaction.
 *
 * Bulk safe: one Task per changed Opportunity, written with a single insert
 * statement per trigger execution.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    @TestVisible
    private static final Set<Id> opportunityIdsSeenAfterUpdate = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        if (triggerOld != null) {
            oldById.putAll(triggerOld);
        }

        List<Task> tasksToInsert = new List<Task>();
        for (Opportunity opp : triggerNew) {
            // Rounding (or any other action) updates the same Opportunity again in this
            // transaction. Only the first pass reflects the change the user made, so
            // everything after that is ignored for this Opportunity.
            if (!opportunityIdsSeenAfterUpdate.add(opp.Id)) {
                continue;
            }
            Opportunity oldOpp = oldById.get(opp.Id);
            if (oldOpp == null || opp.Amount == oldOpp.Amount) {
                continue;
            }
            tasksToInsert.add(new Task(
                Subject = 'Amount changed',
                WhatId = opp.Id,
                Status = 'Completed'
            ));
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
